async function persistIdentityProfile({ realName, nickname, phone, birthYear, neighborhood, gender, profileEditor = false, profileStyle = null }) {
  const normalizedRealName = normalizeIdentityText(realName);
  const normalizedNickname = normalizeIdentityText(nickname);
  const normalizedPhone = normalizeIdentityPhone(phone);
  const normalizedBirthYear = Number(birthYear) || 0;
  const normalizedNeighborhood = normalizeIdentityText(neighborhood);
  const normalizedGender = String(gender || "");
  if (!normalizedRealName || normalizedRealName.length > 40) throw new Error("real_name_invalid");
  if (normalizedNickname.length < 2 || normalizedNickname.length > 20) throw new Error("nickname_invalid");
  if (!/^01[0-9]{8,9}$/u.test(normalizedPhone) && !(profileEditor && normalizedPhone === profilePhoneExpectedPhone)) throw new Error("phone_invalid");
  if (!profileEditor && (normalizedBirthYear < 1900 || normalizedBirthYear > new Date().getFullYear())) throw new Error("birth_year_invalid");
  if (!profileEditor && !["female", "male", "other", "prefer_not"].includes(normalizedGender)) throw new Error("gender_invalid");
  const client = window.TennisNoteDataClient;
  const signupOwner = !profileEditor && hasLiveMemberSession() ? {
    authId: String(state.member?.authUserId || ""),
    profileId: String(state.member?.profileId || ""),
    sessionToken: client?.getSession?.()?.access_token || "",
  } : null;
  const signupContextCurrent = (profileId = signupOwner?.profileId) => Boolean(signupOwner
    && window.TennisNoteDataClient === client && hasLiveMemberSession()
    && signupOwner.sessionToken === client?.getSession?.()?.access_token
    && signupOwner.authId === String(state.member?.authUserId || "")
    && profileId === String(state.member?.profileId || ""));
  if (!profileEditor) {
    if (signupOwner && (!signupOwner.authId || !signupOwner.profileId || !client?.rpc)) throw new Error("login_required");
    if (signupOwner && (state.member?.role !== "member" || state.member?.status !== "active")) throw new Error("signup_profile_required");
    // Legacy production also requires verified contact before an offline preview.
    await requireVerifiedIdentityPhone(normalizedPhone);
    if (signupOwner && !signupContextCurrent()) throw new Error("signup_identity_context_changed");
    if (!signupOwner && hasLiveMemberSession()) throw new Error("signup_identity_context_changed");
  }
  if (profileEditor && (!hasLiveMemberSession() || !client?.rpc)) throw new Error("login_required");
  if (hasLiveMemberSession() && client?.rpc) {
    if (profileEditor) {
      const owner = profilePhoneEditorOwner;
      if (!owner?.profileId || !owner.authId || !phoneVerificationRequestCurrent(owner, normalizedPhone, "profile")) throw new Error("profile_phone_context_changed");
      if (normalizedPhone !== profilePhoneExpectedPhone) await requireVerifiedIdentityPhone(normalizedPhone, "profile");
      if (!phoneVerificationRequestCurrent(owner, normalizedPhone, "profile")) throw new Error("profile_phone_context_changed");
      const targetProfile = { name: normalizedRealName, nickname: normalizedNickname, phone: normalizedPhone };
      if (profileStyle !== null) {
        const saved = await updateMemberProfileOnServer(profileStyle, targetProfile);
        if (!saved.ok) throw saved.error;
        if (saved.phoneVerified === true) markIdentityPhoneVerified(normalizedPhone, "server", "profile");
        return saved;
      }
      const fingerprint = JSON.stringify([owner.authId, owner.profileId, profilePhoneExpectedPhone, targetProfile]);
      if (profilePhoneSaveOperation.fingerprint !== fingerprint) profilePhoneSaveOperation = { fingerprint, key: crypto.randomUUID() };
      const resultRaw = await client.rpc("tn_save_my_verified_profile_phone", {
        target_profile_id: owner.profileId, target_profile: targetProfile,
        target_expected_phone: profilePhoneExpectedPhone, target_operation_key: profilePhoneSaveOperation.key,
      });
      if (!phoneVerificationOwnerCurrent(owner)) throw new Error("profile_phone_context_changed");
      const result = Array.isArray(resultRaw) ? resultRaw[0] : resultRaw;
      if (!result?.ok || result.profile?.id !== owner.profileId
        || normalizeIdentityPhone(result.profile?.phone || "") !== normalizedPhone
        || (normalizedPhone !== profilePhoneExpectedPhone && result.phoneVerified !== true)) {
        throw new Error("profile_phone_readback_unconfirmed");
      }
      applySavedIdentity(result.profile, { preserveCompletion: true });
      if (result.phoneVerified === true) markIdentityPhoneVerified(normalizedPhone, "server", "profile");
      else setIdentityPhoneStatus("저장된 번호를 그대로 유지했습니다. 새 번호로 바꾸려면 인증해 주세요.", "", "profile");
      return result;
    }
    const targetProfile = {
      name: normalizedRealName, nickname: normalizedNickname, phoneCandidate: normalizedPhone,
      birthYear: normalizedBirthYear, neighborhood: normalizedNeighborhood,
      gender: normalizedGender, privacyVersion: identityPrivacyVersion,
    };
    // Memory-only draft/key: a lost response retries the same operation. Raw
    // contact is never written to console, URL, analytics or a new storage key.
    // A successful server link may update the visible profile before a later
    // readback fails. Only that exact acknowledged transition retains its key.
    const operationProfileId = signupProfileOperation.authId === signupOwner.authId
      && signupProfileOperation.linkedProfileId === signupOwner.profileId
      ? signupProfileOperation.sourceProfileId : signupOwner.profileId;
    const fingerprint = JSON.stringify([signupOwner.authId, operationProfileId, targetProfile]);
    if (signupProfileOperation.fingerprint !== fingerprint) {
      signupProfileOperation = { fingerprint, key: crypto.randomUUID(), authId: signupOwner.authId,
        sourceProfileId: signupOwner.profileId, linkedProfileId: "" };
    }
    const signupOperation = signupProfileOperation;
    const signupOperationKey = signupOperation.key;
    const rawResult = await retryTransientNetwork(() => {
      if (!signupContextCurrent()) throw new Error("signup_identity_context_changed");
      return client.rpc("tn_save_my_signup_profile", {
        target_profile: targetProfile,
        target_operation_key: signupOperationKey,
      });
    });
    if (!signupContextCurrent()) throw new Error("signup_identity_context_changed");
    const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
    if (!result?.ok || !result?.profile) throw new Error("identity_profile_update_not_confirmed");
    if (!["linked", "approval_pending"].includes(result.linkStatus)
      || !result.profile.id || (result.linkStatus === "approval_pending" && result.profile.id !== signupOwner.profileId)) {
      throw new Error("signup_link_readback_unconfirmed");
    }
    if (result.linkStatus === "linked") {
      signupOperation.linkedProfileId = result.profile.id;
      const restored = await applySupabaseMemberSession(false, {
        expectedProfileId: result.profile.id,
        expectedAuthUserId: signupOwner.authId,
        requireSignupReadback: true,
      });
      if (!restored || !signupContextCurrent(result.profile.id)) throw new Error("signup_link_readback_unconfirmed");
    } else applySavedIdentity(result.profile);
    return result;
  }

  const profile = {
    name: normalizedRealName,
    nickname: normalizedNickname,
    phone: normalizedPhone,
    birth_year: normalizedBirthYear,
    neighborhood: normalizedNeighborhood,
    gender: normalizedGender,
    profile_completed_at: new Date().toISOString(),
    privacy_consent_version: identityPrivacyVersion,
    privacy_consented_at: new Date().toISOString(),
  };
  applySavedIdentity(profile);
  return { ok: true, profile, linkStatus: "offline_preview" };
}
